  "applicable_norms": [
    {
      "policy_source_id": "q14",
      "interpretation": "Compensation must be offered only if the user is a silver/gold member, has travel insurance, or flies business class. Additionally, compensation must be explicitly requested by the user and tied to specific conditions: cancelled flights for silver/gold members or those with travel insurance, or delayed flights with explicit user request to change/cancel.",
      "modality": "FORBID"
    },
    {
      "policy_source_id": "q14",
      "interpretation": "Compensation for cancelled flights must be $100 times the number of passengers, and only offered after confirming facts and user request.",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q13",
      "interpretation": "Do not proactively offer compensation unless explicitly requested by the user.",
      "modality": "FORBID"
    },
    {
      "policy_source_id": "q7",
      "interpretation": "The assistant must obtain explicit user confirmation before taking actions that affect the user's account or status.",
      "modality": "REQUIRE"
    }
  ],
  "supporting_evidence": [
    {
      "source_id": "h22",
      "actor": "user",
      "role": "complainant",
      "fact": "User claims the ORD to PHL flight (May 10) was canceled, causing them to miss a business meeting, and explicitly requests compensation."
    },
    {
      "source_id": "h16",
      "actor": "assistant",
      "role": "system",
      "fact": "Reservation WUNA5K (ORD to PHL) shows as economy class, not business, and no travel insurance for this reservation."
    },
    {
      "source_id": "h2",
      "actor": "user",
      "role": "complainant",
      "fact": "User explicitly states the flight was a business trip and requests compensation for missed meeting."
    },
    {
      "source_id": "q15",
